<?php $filtered=array_values(array_filter($events,function($row)use($kind){return $kind==='todos'||$row['kind']===$kind;}));$total=count($filtered);$pages=max(1,(int)ceil($total/50));$page=min($pages,max(1,isset($_GET['pagina'])&&is_scalar($_GET['pagina'])?(int)$_GET['pagina']:1));$visible=array_slice($filtered,($page-1)*50,50); ?>
