<div class="rc-cards rc-plan-cards"><?php foreach(array('ativos'=>array('Titulares ativos','green'),'desativados'=>array('Titulares desativados','red'),'todos'=>array('Todos os planos','blue')) as $key=>$card): ?><a class="rc-stat <?=$card[1]?> <?=$state===$key?'is-selected':''?>" href="<?=rc_h(rc_url(array('situacao'=>$key)))?>"><span><?=$card[0]?></span><strong><?=$key==='todos'?count($plans):$totals[$key]?></strong><small><?=$state===$key?'Filtro selecionado':'Clique para filtrar'?></small></a><?php endforeach; ?><div class="rc-stat purple"><span>Receita mensal prevista</span><strong><?=rc_money($revenue)?></strong><small>Valor dos planos × ativos e adicionais</small></div></div>
<form class="rc-panel rc-filters"><input type="hidden" name="situacao" value="<?=rc_h($state)?>"><label class="rc-grow">Pesquisar plano<input name="busca" value="<?=rc_h($search)?>" placeholder="Nome do plano"></label><button class="rc-primary">Pesquisar</button><a href="<?=rc_h(rc_url(array('busca'=>'')))?>">Limpar</a></form>
<?php
$piePlans=array();$piePrices=array();$planDetails=array();$priceDetails=array();
foreach($plans as $plan){
 if($search!==''&&stripos($plan['nome'],$search)===false)continue;
 $n=$state==='desativados'?(int)$plan['inactive_count']:((int)$plan['active_count']+(int)$plan['additional_count']+($state==='todos'?(int)$plan['inactive_count']:0));
 if($n<=0)continue;
 $piePlans[$plan['nome']]=$n;
 $price=rc_money($plan['valor']);$piePrices[$price]=($piePrices[$price]??0)+$n;
 $detail=array('plan'=>$plan['nome'],'value'=>$price,'count'=>$n,'total'=>rc_money($n*(float)$plan['valor']),'url'=>rc_plan_clients_url($plan['nome'],$state));
 $planDetails[$plan['nome']]=array($detail);$priceDetails[$price][]=$detail;
}
?>
<div class="rc-pies"><?php foreach(array('Clientes por plano'=>$piePlans,'Clientes por mensalidade'=>$piePrices) as $pieTitle=>$pieValues): ?><section class="rc-panel"><div class="rc-panel-heading"><h2><?=rc_h($pieTitle)?></h2><span class="rc-muted"><?=array_sum($pieValues)?> cliente(s)</span></div><p class="rc-muted">Seleção: <?=rc_h(array('ativos'=>'ativos e adicionais','desativados'=>'titulares desativados','todos'=>'todos os cadastros')[$state])?></p><p class="rc-pie-instruction"><strong>Clique na pizza e selecione os planos para filtrar abaixo.</strong></p><?=rc_pie($pieValues,$pieTitle,$pieTitle==='Clientes por plano'?$planDetails:$priceDetails)?></section><?php endforeach; ?></div>
<p class="rc-muted">Valor = mensalidade da tabela de planos. Total = valor × quantidade de clientes, sem descontos ou acréscimos individuais; não representa pagamentos recebidos.</p>
<div class="rc-plan-tables" id="rc-plan-tables"><?php foreach(array('ativos'=>'Clientes ativos','desativados'=>'Clientes desativados') as $tableState=>$tableTitle): ?>
<section class="rc-panel rc-plan-table <?=$tableState==='ativos'?'green':'red'?>"><h2><?=$tableTitle?></h2><?php if($tableState==='ativos'): ?><p class="rc-muted">Inclui titulares ativos e adicionais; adicionais identificados abaixo do nome.</p><?php else: ?><p class="rc-muted">Titulares desativados.</p><?php endif; ?><div class="rc-table-wrap"><table class="rc-table rc-plans-table"><thead><tr><th>Nome do plano</th><th>Valor</th><th>Clientes</th><th>Total</th></tr></thead><tbody>
<?php $tableCount=0;$tableTotal=0;$tableShown=0;foreach($plans as $plan): if($search!==''&&stripos($plan['nome'],$search)===false)continue;
$n=$tableState==='ativos'?(int)$plan['active_count']+(int)$plan['additional_count']:(int)$plan['inactive_count'];$amount=$n*(float)$plan['valor'];$tableCount+=$n;$tableTotal+=$amount;$tableShown++;
?><tr data-rc-plan="<?=rc_h($plan['nome'])?>" data-rc-count="<?=$n?>" data-rc-amount="<?=round($amount*100)?>"><td data-label="Nome do plano"><a class="rc-plan-link" href="<?=rc_h(rc_plan_clients_url($plan['nome'],$tableState))?>"><strong><?=rc_h($plan['nome'])?></strong></a><?php if($tableState==='ativos'&&(int)$plan['additional_count']>0): ?><small><?=$plan['additional_count']?> adicional(is)</small><?php endif; ?></td><td data-label="Valor"><?=rc_money($plan['valor'])?></td><td data-label="Clientes"><span class="rc-pill <?=$tableState==='ativos'?'green':'red'?>"><?=$n?></span></td><td data-label="Total"><strong><?=rc_money($amount)?></strong></td></tr><?php endforeach; ?>
<?php if(!$tableShown): ?><tr><td colspan="4" class="rc-empty">Nenhum plano encontrado.</td></tr><?php endif; ?></tbody><tfoot><tr><th>Total</th><td></td><th><?=$tableCount?></th><th><?=rc_money($tableTotal)?></th></tr></tfoot></table></div></section>
<?php endforeach; ?></div>
<?php endif; endif; ?>
